import{z as s,x as B,o as t,c as p,q as n,j as A,D as r,d as E,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"互联网拓扑与 IXP","description":"","frontmatter":{"title":"互联网拓扑与 IXP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/internet-ixp.md","filePath":"cs/internet-ixp.md","lastUpdated":1791063341000}'),P={name:"cs/internet-ixp.md"};function d(I,a,S,X,m,h){const i=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="互联网拓扑与-ixp" tabindex="-1">互联网拓扑与 IXP <a class="header-anchor" href="#互联网拓扑与-ixp" aria-label="Permalink to &quot;互联网拓扑与 IXP&quot;">​</a></h1><div class="epigraph"><p>AS 图不是随机图：客户–提供者层次加上 IXP 上的多边对等，让流量尽量在公共交换点「落地」而不绕供应商。</p><footer>—— 据 Gao and Rexford, IEEE/ACM ToN 2001 政策稳定；RFC 7948 IXP 相关讨论；CAIDA AS 关系研究通识整理</footer></div><p><a href="/cs/bgp-hijack-rpki">上一课</a> 护源。流量实际走哪张图？缺口是<strong>拓扑</strong>：层级、富俱乐部、IXP 交换机把许多 AS 接到同一二层。本课不把 MPLS TE 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只有转供，小 AS 的流量爬到全球供应商再下来，贵且绕。IXP：共同交费连一台（或一组）交换机，双边/多边对等交换客户路由。这是「付费进房 + BGP」，不是免费全互联。拓扑测量：控制面看到的 AS_PATH 与数据面实际下一跳可能因热土豆不一致。RPKI 不画这张图，只验证源。</p><p><span class="marginnote">直觉类比：转供像每次出门都叫同一家网约车按里程计费；IXP 对等像邻居间约定「顺路免费捎带」——大家把车开进同一个停车场（交换机房），直接换乘客，长途账单立刻变短。</span></p><p>不要把 IXP 写成一个 AS：它通常不转供，只提供二层。</p><p><span class="marginnote">Gao–Rexford 条件保证某类政策下无永久振荡。route server 在 IXP 上减会话，像公共 RR。本课不点名具体交换点当广告。</span></p><h3 id="ixp-不转供" tabindex="-1">IXP 不转供 <a class="header-anchor" href="#ixp-不转供" aria-label="Permalink to &quot;IXP 不转供&quot;">​</a></h3><p>二层汇合加多方 BGP，不是一个 AS。对等无 SLA 也会拥塞。控制面路径与热土豆数据面可以分叉。</p><p><span class="marginnote">常见误区：初学者容易把 IXP 想成一个「超级 AS」替大家转发流量；实际上它通常只提供二层交换和路由服务器，不卖转供。另外免费对等也不承诺质量，端口打满照样拥塞丢包。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：层级供应商 + IXP 横边。对照校园以太网：IXP 也学 MAC，但上面跑很多 eBGP。LACP/MLAG 在 IXP 交换侧防单点，与校园同类。</p>',13)),(t(),A(o,null,{default:r(()=>[l(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUB%5B%22%E5%AD%98%E6%A0%B9%20AS%22%5D%20--%3E%20P%5B%22%E6%8F%90%E4%BE%9B%E8%80%85%22%5D%0A%20%20STUB%20--%3E%20IXP%5B%22IXP%20%E4%BA%8C%E5%B1%82%22%5D%0A%20%20P2%5B%22%E5%8F%A6%E4%B8%80%20AS%22%5D%20--%3E%20IXP%0A%20%20IXP%20--%3E%20BGP%5B%22%E5%A4%9A%E8%BE%B9%E5%AF%B9%E7%AD%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"流量工程后课会在这张图上挪入口。BGP 收敛事件在富连接图上扩散更快也更乱。卫星用户仍经关口 AS 进这张图。主干任播课：根 DNS 常出现在 IXP，是拓扑选择不是协议新字段。",-1)),a[5]||(a[5]=e("p",null,"route server：多边对等的控制面中心，数据面仍直连 IXP 交换机。",-1)),a[6]||(a[6]=e("p",null,"有 IXP 与无 IXP 时，同一对 AS 之间的流量路径差多少，对照着看。",-1)),(t(),A(o,null,{default:r(()=>[l(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%B0%8F%20AS%20%E5%8F%91%E6%B5%81%E9%87%8F%E7%BB%99%E7%9B%AE%E6%A0%87%20AS%22%5D%20--%3E%20WO%7B%22%E6%97%A0%20IXP%22%7D%0A%20%20WO%20--%3E%20P1%5B%22%E4%B8%8A%E8%A1%8C%E4%BB%98%E8%B4%B9%E4%BE%9B%E5%BA%94%E5%95%86%E5%88%B0%E9%AA%A8%E5%B9%B2%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E9%AA%A8%E5%B9%B2%E5%86%8D%E4%B8%8B%E8%A1%8C%EF%BC%9A%E8%B7%AF%E5%BE%84%E9%95%BF%E4%B8%94%E6%8C%89%E9%87%8F%E8%AE%A1%E8%B4%B9%22%5D%0A%20%20S%20--%3E%20WI%7B%22%E6%9C%89%20IXP%22%7D%0A%20%20WI%20--%3E%20RS%5B%22IXP%20%E4%BA%A4%E6%8D%A2%E6%9C%BA%E7%9B%B4%E6%8E%A5%E5%AF%B9%E7%AD%89%22%5D%0A%20%20RS%20--%3E%20D%5B%22%E4%B8%80%E4%B8%A4%E8%B7%B3%E8%90%BD%E5%9C%B0%EF%BC%9A%E7%9C%81%E8%BD%AC%E4%BE%9B%E8%B4%B9%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：两个小 AS 各自连着付费供应商，互发流量要「上行到骨干、骨干再下行」，常常穿过十来个 AS；若两边接进同一个 IXP，同一台交换机就能直达，路径缩到两三个 AS。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 peeringDB 的运维流程。流量工程是下一课。后课默认：互联网 = 政策图 + IXP 横连；不是 OSPF 一张度量图。</p><p>公开对等不等于承诺无拥塞：无 SLA 的对等口会满。</p><p>下一课<a href="/cs/traffic-engineering">流量工程</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AS 关系决定默认路径；IXP 提供短的对等边。</li><li>IXP 是二层汇合，不是转供 AS。</li><li>控制面路径与数据面可能因热土豆分叉。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Gao–Rexford, 2001；IXP 运维通识。</li></ul>',7))])}const D=s(P,[["render",d]]);export{u as __pageData,D as default};
